entries[300149] = { ["name"] = "Leisegleiter", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die von Natur aus in dieser Kreatur gespeicherten Gase ermöglichen es ihr, sowohl in den Tiefen zu überleben als auch in der Luft zu schweben.\"\nBeute von:\nLautlos\nZone:\nNazjatar" }
entries[300150] = { ["name"] = "Fabius", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei. Kann nur unter Wasser benutzt werden.\n\"Er erhebt sich aus dem Wasser, seine Flossen schwingen locker im Wind, die Sonne lässt seine Schuppen glitzern. Er ist einfach... fabihaft.\"\nBeute von:" }
entries[300151] = { ["name"] = "Tintengeschuppter Tiefensucher", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei. Kann nur unter Wasser benutzt werden.\n\"Gezeitenhengste jagen in Schwärmen, indem sie ihre Beute immer und immer wieder mit ihren muskulösen Brustkörben rammen.\"\nVerkäufer:\nMagor Geistbeuger\nZone:\nNazjatar\nKosten:\n150\n\nVerkäufer:\nDazzerian\nZone:\nNazjatar\nKosten:\n150" }
