entries[300265] = { ["name"] = "Persönlicher Zeitverschieber", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nKiste mit E.R.S.A.T.Z.-Teilen (2), Energiezelle (2), Kettenentzündungsspule\nPersönlicher Zeitverschieber\n(3)\nWird beim Aufheben gebunden\nBenutzen: Reist in eine alternative Zukunft Mechagons. (5 Min Abklingzeit)\n\"Ein hochmodernes Gerät, das Euch durch die Zeit verschieben kann.\"" }
entries[300266] = { ["name"] = "Orangefarbener Sprühbot", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErsatzteile (50)\nOrangefarbener Sprühbot\n(20)\nWird beim Aufheben gebunden\nBenutzen: Erschafft einen mit oranger Farbe befüllten Sprühbot. (5 Min Abklingzeit)\n\"Ein autonomer, mit orangener Farbe befüllter Sprühbot.\"" }
entries[300267] = { ["name"] = "Grüner Sprühbot", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErsatzteile (50)\nGrüner Sprühbot\n(20)\nWird beim Aufheben gebunden\nBenutzen: Erschafft einen mit grüner Farbe befüllten Sprühbot. (5 Min Abklingzeit)\n\"Ein autonomer, mit grüner Farbe befüllter Sprühbot.\"" }
entries[300268] = { ["name"] = "Blauer Sprühbot", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErsatzteile (50)\nBlauer Sprühbot\n(20)\nWird beim Aufheben gebunden\nBenutzen: Erschafft einen mit blauer Farbe befüllten Sprühbot. (5 Min Abklingzeit)\n\"Ein autonomer, mit blauer Farbe befüllter Sprühbot.\"" }
entries[300269] = { ["name"] = "Mechanomehrzweckklaue", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nKiste mit E.R.S.A.T.Z.-Teilen (3), Energiezelle (3), Kettenentzündungsspule (5)\nMechanomehrzweckklaue\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n1 - 80 ( 80)" }
entries[300270] = { ["name"] = "Mikrobot XD", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nKiste mit E.R.S.A.T.Z.-Teilen (5), Energiezelle (4), Kettenentzündungsspule (2)\nMikrobot XD\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n1 - 80 ( 80)" }
entries[300271] = { ["name"] = "Perfekt eingestelltes Differential", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nKiste mit E.R.S.A.T.Z.-Teilen (2), Energiezelle (5), Galvanischer Oszillator (2)\nPerfekt eingestelltes Differential\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Vision der Perfektion'.\n50" }
entries[300272] = { ["name"] = "Antigravitationsrucksack", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErsatzteile (200), Energiezelle (2)\nAntigravitationsrucksack\n(3)\nWird beim Aufheben gebunden\nBenutzen: Legt den Antigravitationsrucksack an, der mit einem Doppelsprung aktiviert werden kann. Hält 20 Min. lang an. Kann nur in Mechagon verwendet werden. (1 Min Abklingzeit)" }
entries[300273] = { ["name"] = "Taschengeschütz des Rostbolzens", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErsatzteile (50), Energiezelle (3)\n(5)\nWird beim Aufheben gebunden\nBenutzen: Wirft ein Flammengeschütz auf den Boden, das den Bereich 2 Minuten lang verteidigt. Kann nur in Zandalar und Kul Tiras verwendet werden. (1 Min Abklingzeit)" }
entries[300274] = { ["name"] = "Nerv-o-Tron-Bande", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErsatzteile (50), Energiezelle\n(5)\nWird beim Aufheben gebunden\nBenutzen: Lässt nervige Roboter auf ein Gebiet los, um dort 30 Sek. lang alle Gegner aufzudecken und abzulenken. Kann nur in Zandalar und Kul Tiras verwendet werden. (1 Min Abklingzeit)" }
entries[300275] = { ["name"] = "Verschlüsseltes Schwarzmarktfunkgerät", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErsatzteile (150), Energiezelle , Kettenentzündungsspule\nVerschlüsseltes Schwarzmarktfunkgerät\n(5)\nWird beim Aufheben gebunden\nBenutzen: Beantragt Zugriff auf das Schwarzmarktauktionshaus. (5 Min Abklingzeit)\n\"Gebt von überall aus Gebote ab.\"" }
entries[300276] = { ["name"] = "Brutstättenei" }
entries[300277] = { ["name"] = "Reprozedural erzeugte Lochkarte", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nKiste mit E.R.S.A.T.Z.-Teilen , Energiezelle , Galvanischer Oszillator\nErschafft eine zufällige gelbe Lochkarte für Euer Rechengerät im Taschenformat.\nReprozedural erzeugte Lochkarte\nWird beim Aufheben gebunden\n\"Erschafft eine zufällige gelbe Lochkarte für Euer Rechengerät im Taschenformat.\"\n<Zum Öffnen rechtsklicken>" }
entries[300278] = { ["name"] = "Galvanischer Oszillator", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nKettenentzündungsspule , Energiezelle (5), Ersatzteile (150)\nGalvanischer Oszillator\nMechagontüfteleien\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Ein essentieller Bestandteil der fortgeschrittensten Verstärkungen.\"" }
entries[300279] = { ["name"] = "Kettenentzündungsspulen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGalvanischer Oszillator , Energiezelle (2), Kiste mit E.R.S.A.T.Z.-Teilen\nKettenentzündungsspule\n(3)\nMechagontüfteleien\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Wird in den leistungsstärksten Antrieben verwendet.\"" }
entries[300291] = { ["name"] = "Kiste mit E.R.S.A.T.Z.-Teilen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErsatzteile (250)\nKiste mit E.R.S.A.T.Z.-Teilen\nMechagontüfteleien\nWird beim Aufheben gebunden\nBenutzen: Entpackt eine Kiste mit E.R.S.A.T.Z.-Teilen, um an den Inhalt zu gelangen.\nHandwerksmaterial\n\"250 Ersatzteile, die ordentlich angeordnet sind.\"" }
